const S = 50;
const CLRS = "6b2737-e08e45-f8f4a6-bdf7b7-3943b7"
  .split("-")
  .map((i) => "#" + i);
let BG = "#000008";
let x = 0, y = S;

function setup() {
  createCanvas(400, 400);
	pixelDensity(1);
	describe("animation of wave lines")
  frameRate(10);
  noStroke();
  background(0, 0, 8);
	BG += "20";
}


function draw() {
	blendMode(BLEND)
	background(0, 0, 8, 12);
	blendMode(ADD)
	for (let i = 0; i < 4; i++) {
		stroke(lerpColor(color(CLRS[3]), color(CLRS[4]), random()));
		strokeWeight(~~random(1,4));
		drawRectA(~~random(-width*0.5, width), ~~random(height), ~~random(width * 0.25, width * 1.5), ~~random(4, height * 0.1))
	}

	push();
	blendMode(BLEND)
  stroke(0);
  fill(255);
  text("#minacoding 24/09 A year ago", 0, 10);
  pop();
}

function drawRectA(x, y, w, h) {
	for (let xx = x; xx < x + w; xx += h) {
		if (random()<0.75) line(xx, y + h, xx + h, y);
		if (random()<0.5) line(xx + h, y + h, xx + h, y);
	}
}
